export function emptyCompletionContext(opts) {
    return {
        runId: opts.runId ?? '',
        policy: opts.policy,
        timeUp: false,
        pauseCount: 0,
        durable: null,
        recovery: undefined,
        history: opts.history ?? [],
        failureResults: {},
        response: '',
        sources: [],
        availableTools: [],
        promptPrefix: '',
        round: 0,
        roundsSent: 0,
        mute: 0,
        cuts: 0,
        narrated: false,
        malformed: false,
        webSearches: 0,
        directSearchDone: false,
        pendingSearch: null,
        cappedRounds: 0,
        deniedKeys: [],
        failedCalls: {},
        blockedRepeats: 0,
        settledResults: {},
        roundProgressed: false,
        answer: null,
        delivered: false,
        deliveredThisRound: false,
        activated: [],
        outcome: null,
        metrics: {
            tokens: 0,
            timedTokens: 0,
            decodeMs: 0,
            ctxSize: opts.ctxSize,
            rounds: [],
            tools: []
        },
        agentId: opts.agentId ?? null,
        cacheKey: opts.cacheKey ?? null,
        lastRound: null,
        prepareStep: null,
        pendingCall: null,
        approval: { status: 'idle', key: null },
        currentCall: null,
        execution: null,
        rejectedCall: null,
        toolQueue: [],
        cappedCalls: 0,
        resolvedCount: 0,
        failure: null,
        failMessage: null,
        steering: [],
        followUps: [],
        edgeInputs: [],
        plan: opts.plan ?? [],
        planMode: opts.planMode ?? false,
        goal: opts.goal
            ? {
                objective: opts.goal.objective,
                tokens: opts.goal.tokens ?? null,
                turns: 0,
                status: 'open',
                checks: (opts.goal.checks ?? []).map((name) => ({ name, passed: false, output: null })),
                named: (opts.goal.checksProve && Boolean(opts.goal.checks?.length)) || undefined
            }
            : null
    };
}
